RETURNS TRIGGER AS $$
DECLARE
    risk_score NUMERIC;
BEGIN 
    -- Get the risk score of the case
    SELECT risksc INTO risk_score
    FROM compliancecase
    WHERE compreg = NEW.compref2;

    -- Check if the case has a high risk score
    IF risk_score > 70 THEN 
        RAISE EXCEPTION 'Cannot resolve case with high risk score'; 
    END IF;

    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

